//***********************************************************************
//  Field multiplication in GF(p)
//  Operation: c = a x b mod p
//  Inputs: a stored in [x1], b stored in [x2]
//  Output: c stored in [x0]
//  Register allocation: a (resident) = x3..x12;
//                       acc z0..z10 = x13..x17,x19..x24,
//                       scalar bi = x25, MULADD temp x26;
//                       the reduction borrows bi (dead there).
//***********************************************************************
.global CDECL(fp_mul)
.p2align 6
CDECL(fp_mul):
    stp   x19, x20, [sp, #-64]!
    stp   x21, x22, [sp, #16]
    stp   x23, x24, [sp, #32]
    stp   x25, x26, [sp, #48]
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    // x13..x17,x19..x24 <- z = a x b0
    ldr   x25, [x2]
    MUL64x640  x13,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x25, x26
