    // reduce x24,x13..x17,x19..x22 into [0, p)
    mov   x26, #-1
    movn  x25, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x24, x24, x26
    sbcs  x13, x13, x26
    sbcs  x14, x14, x26
    sbcs  x15, x15, x26
    sbcs  x16, x16, x26
    sbcs  x17, x17, x26
    sbcs  x19, x19, x26
    sbcs  x20, x20, x26
    sbcs  x21, x21, x26
    sbcs  x22, x22, x25
    sbc   x26, xzr, xzr              // mask = -borrow
    and   x25, x25, x26
    adds  x24, x24, x26
    adcs  x13, x13, x26
    adcs  x14, x14, x26
    adcs  x15, x15, x26
    adcs  x16, x16, x26
    adcs  x17, x17, x26
    adcs  x19, x19, x26
    adcs  x20, x20, x26
    adcs  x21, x21, x26
    adc   x22, x22, x25
    stp   x24, x13, [x0]
    stp   x14, x15, [x0, #16]
    stp   x16, x17, [x0, #32]
    stp   x19, x20, [x0, #48]
    stp   x21, x22, [x0, #64]
    ldp   x25, x26, [sp, #48]
    ldp   x23, x24, [sp, #32]
    ldp   x21, x22, [sp, #16]
    ldp   x19, x20, [sp], #64
    ret

