    ldp   x15, x16, [x1, #16]
    ldp   x17, x19, [x1, #32]
    ldp   x20, x21, [x1, #48]
    ldp   x22, x23, [x1, #64]
    ldp   x25, x26, [x1, #80]
    adds  x13, x13, x25
    adcs  x14, x14, x26
    ldp   x25, x26, [x1, #96]
    adcs  x15, x15, x25
    adcs  x16, x16, x26
    ldp   x25, x26, [x1, #112]
    adcs  x17, x17, x25
    adcs  x19, x19, x26
    ldp   x25, x26, [x1, #128]
    adcs  x20, x20, x25
    adcs  x21, x21, x26
    ldp   x25, x26, [x1, #144]
    adcs  x22, x22, x25
    adc   x23, x23, x26
    stp   x13, x14, [sp]
    stp   x15, x16, [sp, #16]
    stp   x17, x19, [sp, #32]
    stp   x20, x21, [sp, #48]
    stp   x22, x23, [sp, #64]
    // r = b0 + b1 (unreduced, < 2p) -> x3..x12
