    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x9, x10, [x2, #48]
    ldp   x11, x12, [x2, #64]
    ldp   x25, x26, [x2, #80]
    adds  x3, x3, x25
    adcs  x4, x4, x26
    ldp   x25, x26, [x2, #96]
    adcs  x5, x5, x25
    adcs  x6, x6, x26
    ldp   x25, x26, [x2, #112]
    adcs  x7, x7, x25
    adcs  x8, x8, x26
    ldp   x25, x26, [x2, #128]
    adcs  x9, x9, x25
    adcs  x10, x10, x26
    ldp   x25, x26, [x2, #144]
    adcs  x11, x11, x25
    adc   x12, x12, x26

