    // reduce x24,x13..x17,x19..x22 into [0, p)
    mov   x25, #-1
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x24, x24, x25
    sbcs  x13, x13, x25
    sbcs  x14, x14, x25
    sbcs  x15, x15, x25
    sbcs  x16, x16, x25
    sbcs  x17, x17, x25
    sbcs  x19, x19, x25
    sbcs  x20, x20, x25
    sbcs  x21, x21, x25
    sbcs  x22, x22, x26
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x24, x24, x25
    adcs  x13, x13, x25
    adcs  x14, x14, x25
    adcs  x15, x15, x25
    adcs  x16, x16, x25
    adcs  x17, x17, x25
    adcs  x19, x19, x25
    adcs  x20, x20, x25
    adcs  x21, x21, x25
    adc   x22, x22, x26
    stp   x24, x13, [sp]
    stp   x14, x15, [sp, #16]
    stp   x16, x17, [sp, #32]
    stp   x19, x20, [sp, #48]
    stp   x21, x22, [sp, #64]

