    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x9, x10, [x2, #48]
    ldp   x11, x12, [x2, #64]
    // x24,x13..x17,x19..x23 <- z = a x b0
    ldr   x25, [x1]
    MUL64x640  x24,x13,x14,x15,x16,x17,x19,x20,x21,x22,x23, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x25, x26
    FPMUL640x640  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x24,x13,x14,x15,x16,x17,x19,x20,x21,x22,x23, x25, x26
    // reduce x23,x24,x13..x17,x19..x21 into [0, p)
    mov   x25, #-1
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x23, x23, x25
    sbcs  x24, x24, x25
    sbcs  x13, x13, x25
    sbcs  x14, x14, x25
    sbcs  x15, x15, x25
    sbcs  x16, x16, x25
    sbcs  x17, x17, x25
    sbcs  x19, x19, x25
    sbcs  x20, x20, x25
    sbcs  x21, x21, x26
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x23, x23, x25
    adcs  x24, x24, x25
    adcs  x13, x13, x25
    adcs  x14, x14, x25
    adcs  x15, x15, x25
    adcs  x16, x16, x25
    adcs  x17, x17, x25
    adcs  x19, x19, x25
    adcs  x20, x20, x25
    adc   x21, x21, x26
    stp   x23, x24, [sp, #80]
    stp   x13, x14, [sp, #96]
    stp   x15, x16, [sp, #112]
    stp   x17, x19, [sp, #128]
    stp   x20, x21, [sp, #144]

    // P1 = b1 x a1 -> x23,x24,x13..x17,x19..x21
    ldp   x3, x4, [x2, #80]
    ldp   x5, x6, [x2, #96]
    ldp   x7, x8, [x2, #112]
    ldp   x9, x10, [x2, #128]
    ldp   x11, x12, [x2, #144]
    add   x1, x1, #80                // a1; a and b are dead after P1
    // x23,x24,x13..x17,x19..x22 <- z = a x b0
    ldr   x25, [x1]
    MUL64x640  x23,x24,x13,x14,x15,x16,x17,x19,x20,x21,x22, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x25, x26
    FPMUL640x640  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x23,x24,x13,x14,x15,x16,x17,x19,x20,x21,x22, x25, x26
    // reduce x22..x24,x13..x17,x19,x20 into [0, p)
    mov   x25, #-1
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x22, x22, x25
    sbcs  x23, x23, x25
    sbcs  x24, x24, x25
    sbcs  x13, x13, x25
    sbcs  x14, x14, x25
    sbcs  x15, x15, x25
    sbcs  x16, x16, x25
    sbcs  x17, x17, x25
    sbcs  x19, x19, x25
    sbcs  x20, x20, x26
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x22, x22, x25
    adcs  x23, x23, x25
    adcs  x24, x24, x25
    adcs  x13, x13, x25
    adcs  x14, x14, x25
    adcs  x15, x15, x25
    adcs  x16, x16, x25
    adcs  x17, x17, x25
    adcs  x19, x19, x25
    adc   x20, x20, x26

    // c0 = P0 - P1 -> x3..x12
    ldp   x3, x4, [sp, #80]
    ldp   x5, x6, [sp, #96]
    ldp   x7, x8, [sp, #112]
    ldp   x9, x10, [sp, #128]
    ldp   x11, x12, [sp, #144]
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x3, x3, x22
    sbcs  x4, x4, x23
    sbcs  x5, x5, x24
    sbcs  x6, x6, x13
    sbcs  x7, x7, x14
    sbcs  x8, x8, x15
    sbcs  x9, x9, x16
    sbcs  x10, x10, x17
    sbcs  x11, x11, x19
    sbcs  x12, x12, x20
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x3, x3, x25
    adcs  x4, x4, x25
    adcs  x5, x5, x25
    adcs  x6, x6, x25
    adcs  x7, x7, x25
    adcs  x8, x8, x25
    adcs  x9, x9, x25
    adcs  x10, x10, x25
    adcs  x11, x11, x25
    adc   x12, x12, x26
    stp   x3, x4, [x0]
    stp   x5, x6, [x0, #16]
    stp   x7, x8, [x0, #32]
    stp   x9, x10, [x0, #48]
    stp   x11, x12, [x0, #64]

    // c1 = (P2 - P1) - P0
    ldp   x3, x4, [sp]
    ldp   x5, x6, [sp, #16]
    ldp   x7, x8, [sp, #32]
    ldp   x9, x10, [sp, #48]
    ldp   x11, x12, [sp, #64]
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x3, x3, x22
    sbcs  x4, x4, x23
    sbcs  x5, x5, x24
    sbcs  x6, x6, x13
    sbcs  x7, x7, x14
    sbcs  x8, x8, x15
    sbcs  x9, x9, x16
    sbcs  x10, x10, x17
    sbcs  x11, x11, x19
    sbcs  x12, x12, x20
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x3, x3, x25
    adcs  x4, x4, x25
    adcs  x5, x5, x25
    adcs  x6, x6, x25
    adcs  x7, x7, x25
    adcs  x8, x8, x25
    adcs  x9, x9, x25
    adcs  x10, x10, x25
    adcs  x11, x11, x25
    adc   x12, x12, x26
    ldp   x22, x23, [sp, #80]
    ldp   x24, x13, [sp, #96]
    ldp   x14, x15, [sp, #112]
    ldp   x16, x17, [sp, #128]
    ldp   x19, x20, [sp, #144]
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x3, x3, x22
    sbcs  x4, x4, x23
    sbcs  x5, x5, x24
    sbcs  x6, x6, x13
    sbcs  x7, x7, x14
    sbcs  x8, x8, x15
    sbcs  x9, x9, x16
    sbcs  x10, x10, x17
    sbcs  x11, x11, x19
    sbcs  x12, x12, x20
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x3, x3, x25
    adcs  x4, x4, x25
    adcs  x5, x5, x25
    adcs  x6, x6, x25
    adcs  x7, x7, x25
    adcs  x8, x8, x25
    adcs  x9, x9, x25
    adcs  x10, x10, x25
    adcs  x11, x11, x25
    adc   x12, x12, x26
    stp   x3, x4, [x0, #80]
    stp   x5, x6, [x0, #96]
    stp   x7, x8, [x0, #112]
    stp   x9, x10, [x0, #128]
    stp   x11, x12, [x0, #144]
    ldp   x25, x26, [sp, #208]
    ldp   x23, x24, [sp, #192]
    ldp   x21, x22, [sp, #176]
    ldp   x19, x20, [sp, #160]
    add   sp, sp, #224
    ret

//***********************************************************************
//  Squaring in GF(p^2)
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//    with a0+a1, a0-a1+p and 2*a0 kept unreduced (< 2p), so both
//    Montgomery products are < 2p before their final reduction.
//  Inputs: a = [a0, a1] stored in [x1]
//  Output: c = [c0, c1] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+p, then a1) = x3..x12;
//                       acc z0..z10 = x13..x17,x19..x24,
//                       scalar bi = x25, MULADD temp x26;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 80) holds s = a0+a1;
//         [sp+80 .. 160) holds t = 2*a0.
//***********************************************************************
.global CDECL(fp2_sqr)
.p2align 6
CDECL(fp2_sqr):
    sub   sp, sp, #224               // 160 for s + t + 64 for callee saves
    stp   x19, x20, [sp, #160]
    stp   x21, x22, [sp, #176]
    stp   x23, x24, [sp, #192]
    stp   x25, x26, [sp, #208]

    // t = 2*a0 (unreduced) -> [sp+80] ; a0 stays in x3..x12
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    adds  x13, x3, x3
    adcs  x14, x4, x4
    adcs  x15, x5, x5
    adcs  x16, x6, x6
    adcs  x17, x7, x7
    adcs  x19, x8, x8
    adcs  x20, x9, x9
    adcs  x21, x10, x10
    adcs  x22, x11, x11
    adc   x23, x12, x12
    stp   x13, x14, [sp, #80]
    stp   x15, x16, [sp, #96]
    stp   x17, x19, [sp, #112]
    stp   x20, x21, [sp, #128]
    stp   x22, x23, [sp, #144]
    // s = a0 + a1 (unreduced) -> [sp]
    ldp   x13, x14, [x1, #80]
    ldp   x15, x16, [x1, #96]
    ldp   x17, x19, [x1, #112]
    ldp   x20, x21, [x1, #128]
    ldp   x22, x23, [x1, #144]
    adds  x13, x13, x3
    adcs  x14, x14, x4
    adcs  x15, x15, x5
    adcs  x16, x16, x6
    adcs  x17, x17, x7
    adcs  x19, x19, x8
    adcs  x20, x20, x9
    adcs  x21, x21, x10
    adcs  x22, x22, x11
    adc   x23, x23, x12
    stp   x13, x14, [sp]
    stp   x15, x16, [sp, #16]
    stp   x17, x19, [sp, #32]
    stp   x20, x21, [sp, #48]
    stp   x22, x23, [sp, #64]
    // d = a0 - a1 + p (unreduced, in (0, 2p)) -> x3..x12
    ldp   x13, x14, [x1, #80]
    subs  x3, x3, x13
    sbcs  x4, x4, x14
    ldp   x13, x14, [x1, #96]
    sbcs  x5, x5, x13
    sbcs  x6, x6, x14
    ldp   x13, x14, [x1, #112]
    sbcs  x7, x7, x13
    sbcs  x8, x8, x14
    ldp   x13, x14, [x1, #128]
    sbcs  x9, x9, x13
    sbcs  x10, x10, x14
    ldp   x13, x14, [x1, #144]
    sbcs  x11, x11, x13
    sbcs  x12, x12, x14
    mov   x13, #-1
    movn  x14, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    adds  x3, x3, x13
    adcs  x4, x4, x13
    adcs  x5, x5, x13
    adcs  x6, x6, x13
    adcs  x7, x7, x13
    adcs  x8, x8, x13
    adcs  x9, x9, x13
    adcs  x10, x10, x13
    adcs  x11, x11, x13
    adc   x12, x12, x14

    // c0 = d x s -> [out] (a0's slot; a1 is still intact if c == a)
    // x13..x17,x19..x24 <- z = a x b0
    ldr   x25, [sp]
    MUL64x640  x13,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x25, x26
    FPMUL640x640  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x13,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24, x25, x26
    // reduce x24,x13..x17,x19..x22 into [0, p)
    mov   x25, #-1
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x24, x24, x25
    sbcs  x13, x13, x25
    sbcs  x14, x14, x25
    sbcs  x15, x15, x25
    sbcs  x16, x16, x25
    sbcs  x17, x17, x25
    sbcs  x19, x19, x25
    sbcs  x20, x20, x25
    sbcs  x21, x21, x25
    sbcs  x22, x22, x26
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x24, x24, x25
    adcs  x13, x13, x25
    adcs  x14, x14, x25
    adcs  x15, x15, x25
    adcs  x16, x16, x25
    adcs  x17, x17, x25
    adcs  x19, x19, x25
    adcs  x20, x20, x25
    adcs  x21, x21, x25
    adc   x22, x22, x26
    stp   x24, x13, [x0]
    stp   x14, x15, [x0, #16]
    stp   x16, x17, [x0, #32]
    stp   x19, x20, [x0, #48]
    stp   x21, x22, [x0, #64]

    // c1 = a1 x t -> [out+80]
    ldp   x3, x4, [x1, #80]
    ldp   x5, x6, [x1, #96]
    ldp   x7, x8, [x1, #112]
    ldp   x9, x10, [x1, #128]
    ldp   x11, x12, [x1, #144]
    add   x1, sp, #80                // x1 is dead after the a1 load: reuse it as the t pointer
    // x24,x13..x17,x19..x23 <- z = a x b0
    ldr   x25, [x1]
    MUL64x640  x24,x13,x14,x15,x16,x17,x19,x20,x21,x22,x23, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x25, x26
    FPMUL640x640  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12, x24,x13,x14,x15,x16,x17,x19,x20,x21,x22,x23, x25, x26
    // reduce x23,x24,x13..x17,x19..x21 into [0, p)
    mov   x25, #-1
    movn  x26, #0xec30, lsl #48      // p[9] = 0x13CFFFFFFFFFFFFF
    subs  x23, x23, x25
    sbcs  x24, x24, x25
    sbcs  x13, x13, x25
    sbcs  x14, x14, x25
    sbcs  x15, x15, x25
    sbcs  x16, x16, x25
    sbcs  x17, x17, x25
    sbcs  x19, x19, x25
    sbcs  x20, x20, x25
    sbcs  x21, x21, x26
    sbc   x25, xzr, xzr              // mask = -borrow
    and   x26, x26, x25
    adds  x23, x23, x25
    adcs  x24, x24, x25
    adcs  x13, x13, x25
    adcs  x14, x14, x25
    adcs  x15, x15, x25
    adcs  x16, x16, x25
    adcs  x17, x17, x25
    adcs  x19, x19, x25
    adcs  x20, x20, x25
    adc   x21, x21, x26
    stp   x23, x24, [x0, #80]
    stp   x13, x14, [x0, #96]
    stp   x15, x16, [x0, #112]
    stp   x17, x19, [x0, #128]
    stp   x20, x21, [x0, #144]
    ldp   x25, x26, [sp, #208]
    ldp   x23, x24, [sp, #192]
    ldp   x21, x22, [sp, #176]
    ldp   x19, x20, [sp, #160]
    add   sp, sp, #224
    ret
